const {hash}=require('./security');function ensureAdmin(db){const row=db.prepare('SELECT COUNT(*) n FROM users').get();if(row.n)return;const username=process.env.DUCK_ADMIN_USER||'admin';const password=process.env.DUCK_ADMIN_PASSWORD||'change-me-now';db.prepare('INSERT INTO users(username,password_hash,role,permissions,created_at) VALUES(?,?,?,?,?)').run(username,hash(password),'admin',JSON.stringify(['*']),new Date().toISOString());console.warn('DuckFlow admin initialized:',username,'(set DUCK_ADMIN_PASSWORD to change default)')}module.exports={ensureAdmin};